  jsonb_build_object('heading','Pensar como cientista','content',jsonb_build_array('Registre pergunta, hipótese, observação e conclusão em campos separados.','Mude uma condição por vez quando houver comparação e ensine que a conclusão vale para o que foi observado.')),
